import { getChannelRefreshToken, handleDashboard } from "./channels";

interface StudioEnv {
  OAUTH_KV: KVNamespace;
  OAUTH_ADMIN_PASSWORD?: string;
  GOOGLE_OAUTH_CLIENT_ID?: string;
  GOOGLE_OAUTH_CLIENT_SECRET?: string;
  META_APP_ID?: string;
  META_APP_SECRET?: string;
  PINTEREST_APP_ID?: string;
  PINTEREST_APP_SECRET?: string;
  X_CLIENT_ID?: string;
  X_CLIENT_SECRET?: string;
}
function json(data: unknown, status = 200): Response {
  return Response.json(data, { status, headers: { "cache-control": "no-store", "x-content-type-options": "nosniff" } });
}
const SESSION_COOKIE = "alpha_studio_session";
const SESSION_SECONDS = 14 * 24 * 60 * 60;
function cookieValue(request: Request, name: string): string {
  for (const part of (request.headers.get("cookie") ?? "").split(";")) {
    const [key, ...value] = part.trim().split("=");
    if (key === name) return value.join("=");
  }
  return "";
}
async function sessionSignature(secret: string, timestamp: string): Promise<string> {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const bytes = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(timestamp)));
  return Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");
}
async function authorized(request: Request, env: StudioEnv): Promise<boolean> {
  const secret = env.OAUTH_ADMIN_PASSWORD ?? "";
  if (!secret) return false;
  const supplied = request.headers.get("x-admin-password") ?? "";
  if (supplied && supplied.length === secret.length && supplied === secret) return true;
  const [timestamp, signature, extra] = cookieValue(request, SESSION_COOKIE).split(".");
  if (!timestamp || !signature || extra || !/^\d+$/.test(timestamp)) return false;
  const issued = Number(timestamp), now = Math.floor(Date.now() / 1000);
  if (!Number.isSafeInteger(issued) || issued > now + 60 || now - issued > SESSION_SECONDS) return false;
  const expected = await sessionSignature(secret, timestamp);
  if (expected.length !== signature.length) return false;
  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ signature.charCodeAt(i);
  return diff === 0;
}
function sessionCookie(value: string, maxAge: number): string {
  return SESSION_COOKIE + "=" + value + "; Path=/; Max-Age=" + maxAge + "; HttpOnly; Secure; SameSite=Strict";
}
